// === DAILY PUZZLE LOGIC ===
const LAUNCH_DATE = new Date(2025, 5, 1); // 1 июня 2025

function getDayNumber() {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  return Math.floor((today - LAUNCH_DATE) / (1000 * 60 * 60 * 24));
}

// Детерминированная перетасовка (одинаковая для всех игроков)
function seededShuffle(arr, seed) {
  const a = [...arr];
  let s = seed;
  for (let i = a.length - 1; i > 0; i--) {
    s = (s * 16807 + 0) % 2147483647;
    const j = s % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function getDailyEntry() {
  const day = getDayNumber();
  const shuffled = seededShuffle(YEARS_DATA.map((_, i) => i), 42);
  const idx = shuffled[((day % shuffled.length) + shuffled.length) % shuffled.length];
  return { entry: YEARS_DATA[idx], dayNumber: day };
}

function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function compareGuess(guess, target) {
  const result = new Array(guess.length).fill("red");
  const g = guess.split(""), t = target.split("");
  const off = target.length - guess.length;
  const used = new Array(target.length).fill(false);
  for (let i = 0; i < guess.length; i++) {
    const ti = i + off;
    if (ti >= 0 && ti < target.length && g[i] === t[ti]) { result[i] = "green"; used[ti] = true; }
  }
  for (let i = 0; i < guess.length; i++) {
    if (result[i] === "green") continue;
    for (let j = 0; j < target.length; j++) {
      if (!used[j] && g[i] === t[j]) { result[i] = "orange"; used[j] = true; break; }
    }
  }
  return result;
}

